mapper.insert:
insert into oa_labor_contract_template (
    template_name, social_type, template_version, template_file_url,
    status, built_in, create_by, create_time, remark
) values (
    #{templateName}, #{socialType}, #{templateVersion}, #{templateFileUrl},
    #{status}, #{builtIn}, #{createBy}, sysdate(), #{remark}
)

mapper.update:
update oa_labor_contract_template
template_name = #{templateName}, social_type = #{socialType}, template_version = #{templateVersion}, template_file_url = #{templateFileUrl}, status = #{status}, built_in = #{builtIn}, update_by = #{updateBy}, remark = #{remark}, update_time = sysdate()
where template_id = #{templateId}

mapper.select:
select template_id, template_name, social_type, template_version, template_file_url, status, built_in, create_by, create_time, update_by, update_time, remark from oa_labor_contract_template
and template_name like concat('%', #{templateName}, '%')
and social_type = #{socialType}
and status = #{status}
order by template_id desc
